INSERT INTO grammar_exercises (id, chapter_id, slug, title, kind, instructions, items, position, is_published)
VALUES (
  'a1000001-0001-4000-8000-000000000201',
  'a1000001-0001-4000-8000-000000000101',
  'ex-1-1-identification',
  'Exercise 1.1 - Identification and Correction',
  'correction',
  'Each sentence below contains a subject-verb agreement error, except a few which are already correct. Rewrite each faulty sentence correctly, and for the correct ones write "Correct."',
  $items1$[{"id":"q1","prompt":"The list of approved candidates are posted on the noticeboard.","answer":"The list of approved candidates is posted on the noticeboard.","accepted":["The list of approved candidates is posted on the noticeboard."],"reason":"Subject is \"list\" (singular), not \"candidates\".","bn_note":null},{"id":"q2","prompt":"Each of the students have submitted their assignment.","answer":"Each of the students has submitted his or her assignment.","accepted":["Each of the students has submitted their assignment.","Each of the students has submitted his or her assignment."],"reason":"\"Each of\" is always singular.","bn_note":null},{"id":"q3","prompt":"The government are introducing a new tax next year.","answer":"The government is introducing a new tax next year.","accepted":["The government is introducing a new tax next year."],"reason":"Collective noun as one unit takes a singular verb in academic writing.","bn_note":null},{"id":"q4","prompt":"Neither the teacher nor the students was ready for the test.","answer":"Neither the teacher nor the students were ready for the test.","accepted":["Neither the teacher nor the students were ready for the test."],"reason":"With \"neither...nor,\" the verb agrees with the nearer subject, \"students\" (plural).","bn_note":null},{"id":"q5","prompt":"The number of accidents on this road have increased.","answer":"The number of accidents on this road has increased.","accepted":["The number of accidents on this road has increased."],"reason":"\"The number of\" is singular.","bn_note":null},{"id":"q6","prompt":"There is several reasons for this decline.","answer":"There are several reasons for this decline.","accepted":["There are several reasons for this decline."],"reason":"The real subject \"reasons\" is plural.","bn_note":null},{"id":"q7","prompt":"A large amount of information were collected during the survey.","answer":"A large amount of information was collected during the survey.","accepted":["A large amount of information was collected during the survey."],"reason":"\"Information\" is uncountable and singular.","bn_note":null},{"id":"q8","prompt":"Ten kilometres are a long way to walk in the heat.","answer":"Ten kilometres is a long way to walk in the heat.","accepted":["Ten kilometres is a long way to walk in the heat.","Ten kilometers is a long way to walk in the heat."],"reason":"A single distance is treated as one quantity: singular verb.","bn_note":null},{"id":"q9","prompt":"The committee has agreed on the final budget.","answer":"Correct","accepted":["Correct","correct","The committee has agreed on the final budget."],"reason":"\"Committee\" as one unit takes the singular \"has.\"","bn_note":null},{"id":"q10","prompt":"The quality of the roads in rural areas are very poor.","answer":"The quality of the roads in rural areas is very poor.","accepted":["The quality of the roads in rural areas is very poor."],"reason":"Subject is \"quality\" (singular), not \"roads\" or \"areas.\"","bn_note":null},{"id":"q11","prompt":"Poverty and illiteracy remains major obstacles to development.","answer":"Poverty and illiteracy remain major obstacles to development.","accepted":["Poverty and illiteracy remain major obstacles to development."],"reason":"Two subjects joined by \"and\" are plural.","bn_note":null},{"id":"q12","prompt":"Everyone in the two classes were given a certificate.","answer":"Everyone in the two classes was given a certificate.","accepted":["Everyone in the two classes was given a certificate."],"reason":"\"Everyone\" is singular.","bn_note":null},{"id":"q13","prompt":"Not only the manager but also the workers is unhappy with the plan.","answer":"Not only the manager but also the workers are unhappy with the plan.","accepted":["Not only the manager but also the workers are unhappy with the plan."],"reason":"With \"not only...but also,\" the verb agrees with the nearer subject, \"workers\" (plural).","bn_note":null},{"id":"q14","prompt":"The data collected over ten years show a clear pattern.","answer":"Correct","accepted":["Correct","correct","The data collected over ten years show a clear pattern.","The data collected over ten years shows a clear pattern."],"reason":"\"Data\" is treated as a plural or mass noun; \"the data ... show\" is acceptable.","bn_note":null},{"id":"q15","prompt":"My knowledge of these topics are limited.","answer":"My knowledge of these topics is limited.","accepted":["My knowledge of these topics is limited."],"reason":"\"Knowledge\" is uncountable and singular; subject is \"knowledge,\" not \"topics.\"","bn_note":null},{"id":"q16","prompt":"A number of students has failed to register on time.","answer":"A number of students have failed to register on time.","accepted":["A number of students have failed to register on time."],"reason":"\"A number of\" means \"several\" and takes a plural verb.","bn_note":null},{"id":"q17","prompt":"The population of the coastal cities have grown rapidly.","answer":"The population of the coastal cities has grown rapidly.","accepted":["The population of the coastal cities has grown rapidly."],"reason":"Subject is \"population\" (singular), not \"cities.\"","bn_note":null},{"id":"q18","prompt":"Neither of the two proposals seem practical.","answer":"Neither of the two proposals seems practical.","accepted":["Neither of the two proposals seems practical."],"reason":"\"Neither\" is singular.","bn_note":null},{"id":"q19","prompt":"Statistics is a subject that many students find difficult.","answer":"Correct","accepted":["Correct","correct","Statistics is a subject that many students find difficult."],"reason":"\"Statistics\" as the name of a subject is singular.","bn_note":null},{"id":"q20","prompt":"The equipment in the laboratories need to be replaced.","answer":"The equipment in the laboratories needs to be replaced.","accepted":["The equipment in the laboratories needs to be replaced."],"reason":"\"Equipment\" is uncountable and singular.","bn_note":null}]$items1$::jsonb,
  1,
  true
)
