INSERT INTO grammar_exercises (id, chapter_id, slug, title, kind, instructions, items, position, is_published)
VALUES (
  'a1000001-0001-4000-8000-000000000202',
  'a1000001-0001-4000-8000-000000000101',
  'ex-1-2-essay-edit',
  'Exercise 1.2 - IELTS Essay Editing',
  'essay_edit',
  'The paragraph below is from a Band 5.5 Task 2 essay. It contains ten subject-verb agreement errors. Find them, then rewrite the whole paragraph correctly.',
  $items2$[{"id":"para1","prompt":"Nowadays, the number of people who works from home have increased dramatically. There is many reasons for this change. First, technology allow employees to stay connected from anywhere. Second, each of the major companies now offer flexible arrangements. However, some managers believes that productivity fall when staff is not in the office. In my opinion, the advantages of remote work outweighs the disadvantages, and this trend are likely to continue.","answer":"Nowadays, the number of people who work from home has increased dramatically. There are many reasons for this change. First, technology allows employees to stay connected from anywhere. Second, each of the major companies now offers flexible arrangements. However, some managers believe that productivity falls when staff are not in the office. In my opinion, the advantages of remote work outweigh the disadvantages, and this trend is likely to continue.","accepted":[],"reason":"Ten corrections: who work; has increased; There are; technology allows; offers; believe; falls; staff are; outweigh; this trend is.","bn_note":null,"corrections":[{"from":"who works","to":"who work","why":"\"who\" refers to \"people\" (plural)"},{"from":"have increased","to":"has increased","why":"subject is \"the number\" (singular)"},{"from":"There is many reasons","to":"There are many reasons","why":"real subject \"reasons\" is plural"},{"from":"technology allow","to":"technology allows","why":"\"technology\" is singular third person"},{"from":"now offer","to":"now offers","why":"\"each of\" is singular"},{"from":"managers believes","to":"managers believe","why":"\"managers\" is plural"},{"from":"productivity fall","to":"productivity falls","why":"\"productivity\" is singular"},{"from":"staff is not","to":"staff are not","why":"focus on individual workers"},{"from":"outweighs","to":"outweigh","why":"subject is \"advantages\" (plural)"},{"from":"this trend are","to":"this trend is","why":"\"trend\" is singular"}]}]$items2$::jsonb,
  2,
  true
)
ON CONFLICT (chapter_id, slug) DO UPDATE SET
